        },
        "kind": {
          "enum": [
            "transport",
            "health",
            "auth",
            "controller_store"
          ]
        },
        "observed_at": {
          "format": "date-time",
          "type": "string"
        },
        "retry_after_s": {
          "minimum": 0,
          "type": "integer"
        },
        "scheduler_effect": {
          "const": "scheduled_callbacks_queued"
        }
      },
      "required": [
        "gateway_id",
        "kind",
        "observed_at",
        "retry_after_s",
        "scheduler_effect"
      ],
      "type": "object"
    },
    "reconcile_ref": {
