      "type": "string"
    },
    "reservation": {
      "additionalProperties": false,
      "properties": {
        "reason": {
          "const": "stop_unproven"
        },
        "reservation_id": {
          "type": "string"
        },
        "state": {
          "const": "held"
        }
      },
      "required": [
        "state",
        "reason"
      ],
      "type": "object"
    },
    "run_id": {
      "minLength": 1,
      "type": "string"
    },
    "schema_version": {
      "const": "chd.worker-run.v1"
    },
    "state": {
      "enum": [
        "unknown",
        "unreachable"
      ]
    }
  },
  "required": [
    "schema_version",
    "run_id",
    "state",
    "outage",
    "reservation",
    "reconcile_ref"
  ],
  "title": "CHD WorkerRun outage or unknown result",
  "type": "object"
}
